(N'S12_3990',N'1970 Plymouth Hemi Cuda',N'Classic Cars',N'1:12',N'Studio M Art Models',N'Very detailed 1970 Plymouth Cuda model in 1:12 scale. The Cuda is generally accepted as one of the fastest original muscle cars from the 1970s. This model is a reproduction of one of the orginal 652 cars built in 1970. Red color.',5663,N'31.92',N'79.80'),
