(N'S18_1367',N'1936 Mercedes-Benz 500K Special Roadster',N'Vintage Cars',N'1:18',N'Studio M Art Models',N'This 1:18 scale replica is constructed of heavy die-cast metal and has all the features of the original: working doors and rumble seat, independent spring suspension, detailed interior, working steering system, and a bifold hood that reveals an engine so accurate that it even includes the wiring. All this is topped off with a baked enamel finish. Color white.',8635,N'24.26',N'53.91'),
(N'S18_1589',N'1965 Aston Martin DB5',N'Classic Cars',N'1:18',N'Classic Metal Creations',N'Die-cast model of the silver 1965 Aston Martin DB5 in silver. This model includes full wire wheels and doors that open with fully detailed passenger compartment. In 1:18 scale, this model measures approximately 10 inches/20 cm long.',9042,N'65.96',N'124.44'),
(N'S18_1662',N'1980s Black Hawk Helicopter',N'Planes',N'1:18',N'Red Start Diecast',N'1:18 scale replica of actual Army''s UH-60L BLACK HAWK Helicopter. 100% hand-assembled. Features rotating rotor blades, propeller blades and rubber wheels.',5330,N'77.27',N'157.69'),
(N'S18_1749',N'1917 Grand Touring Sedan',N'Vintage Cars',N'1:18',N'Welly Diecast Productions',N'This 1:18 scale replica of the 1917 Grand Touring car has all the features you would expect from museum quality reproductions: all four doors and bi-fold hood opening, detailed engine and instrument panel, chrome-look trim, and tufted upholstery, all topped off with a factory baked-enamel finish.',2724,N'86.70',N'170.00'),
