(N'S18_4600',N'1940s Ford truck',N'Trucks and Buses',N'1:18',N'Motor City Art Classics',N'This 1940s Ford Pick-Up truck is re-created in 1:18 scale of original 1940s Ford truck. This antique style metal 1940s Ford Flatbed truck is all hand-assembled. This collectible 1940''s Pick-Up truck is painted in classic dark green color, and features rotating wheels.',3128,N'84.76',N'121.08'),
