(N'S18_4721',N'1957 Corvette Convertible',N'Classic Cars',N'1:18',N'Classic Metal Creations',N'1957 die cast Corvette Convertible in Roman Red with white sides and whitewall tires. 1:18 scale quality die-cast with detailed engine and underbvody. Now you can own The Classic Corvette.',1249,N'69.93',N'148.80'),
