(N'S24_2840',N'1958 Chevy Corvette Limited Edition',N'Classic Cars',N'1:24',N'Carousel DieCast Legends',N'The operating parts of this 1958 Chevy Corvette Limited Edition are particularly delicate due to their precise scale and require special care and attention. Features rotating wheels, working streering, opening doors and trunk. Color dark green.',2542,N'15.91',N'35.36'),
