(N'S24_4258',N'1936 Chrysler Airflow',N'Vintage Cars',N'1:24',N'Second Gear Diecast',N'Features opening trunk,  working steering system. Color dark green.',4710,N'57.46',N'97.39'),
(N'S24_4278',N'1900s Vintage Tri-Plane',N'Planes',N'1:24',N'Unimax Art Galleries',N'Hand crafted diecast-like metal Triplane is Re-created in about 1:24 scale of antique pioneer airplane. This antique style metal triplane is all hand-assembled with many different parts.',2756,N'36.23',N'72.45'),
(N'S24_4620',N'1961 Chevrolet Impala',N'Classic Cars',N'1:18',N'Classic Metal Creations',N'This 1:18 scale precision die-cast reproduction of the 1961 Chevrolet Impala has all the features-doors, hood and trunk that open; detailed 409 cubic-inch engine; chrome dashboard and stick shift, two-tone interior; working steering system; all topped of with a factory baked-enamel finish.',7869,N'32.33',N'80.84'),
(N'S32_1268',N'1980’s GM Manhattan Express',N'Trucks and Buses',N'1:32',N'Motor City Art Classics',N'This 1980’s era new look Manhattan express is still active, running from the Bronx to mid-town Manhattan. Has 35 opeining windows and working lights. Needs a battery.',5099,N'53.93',N'96.31'),
(N'S32_1374',N'1997 BMW F650 ST',N'Motorcycles',N'1:32',N'Exoto Designs',N'Features official die-struck logos and baked enamel finish. Comes with stand.',178,N'66.92',N'99.89'),
(N'S32_2206',N'1982 Ducati 996 R',N'Motorcycles',N'1:32',N'Gearbox Collectibles',N'Features rotating wheels , working kick stand. Comes with stand.',9241,N'24.14',N'40.23'),
(N'S32_2509',N'1954 Greyhound Scenicruiser',N'Trucks and Buses',N'1:32',N'Classic Metal Creations',N'Model features bi-level seating, 50 windows, skylights & glare resistant glass, working steering system, original logos',2874,N'25.98',N'54.11'),
(N'S32_3207',N'1950''s Chicago Surface Lines Streetcar',N'Trains',N'1:32',N'Gearbox Collectibles',N'This streetcar is a joy to see. It has 80 separate windows, electric wire guides, detailed interiors with seats, poles and drivers controls, rolling and turning wheel assemblies, plus authentic factory baked-enamel finishes (Green Hornet for Chicago and Cream and Crimson for Boston).',8601,N'26.72',N'62.14'),
(N'S32_3522',N'1996 Peterbilt 379 Stake Bed with Outrigger',N'Trucks and Buses',N'1:32',N'Red Start Diecast',N'This model features, opening doors, detailed engine, working steering, tinted windows, detailed interior, die-struck logos, removable stakes operating outriggers, detachable second trailer, functioning 360-degree self loader, precision molded resin trailer and trim, baked enamel finish on cab',814,N'33.61',N'64.64'),
(N'S32_4289',N'1928 Ford Phaeton Deluxe',N'Vintage Cars',N'1:32',N'Highway 66 Mini Classics',N'This model features grille-mounted chrome horn, lift-up louvered hood, fold-down rumble seat, working steering system',136,N'33.02',N'68.79'),
(N'S32_4485',N'1974 Ducati 350 Mk3 Desmo',N'Motorcycles',N'1:32',N'Second Gear Diecast',N'This model features two-tone paint with chrome accents, superior die-cast detail , rotating wheels , working kick stand',3341,N'56.13',N'102.05'),
(N'S50_1341',N'1930 Buick Marquette Phaeton',N'Vintage Cars',N'1:50',N'Studio M Art Models',N'Features opening trunk,  working steering system',7062,N'27.06',N'43.64'),
(N'S50_1392',N'Diamond T620 Semi-Skirted Tanker',N'Trucks and Buses',N'1:50',N'Highway 66 Mini Classics',N'This limited edition model is licensed and perfectly scaled for Lionel Trains. The Diamond T620 has been produced in solid precision diecast and painted with a fire baked enamel finish. It comes with a removable tanker and is a perfect model to add authenticity to your static train or car layout or to just have on display.',1016,N'68.29',N'115.75'),
(N'S50_1514',N'1962 City of Detroit Streetcar',N'Trains',N'1:50',N'Classic Metal Creations',N'This streetcar is a joy to see. It has 99 separate windows, electric wire guides, detailed interiors with seats, poles and drivers controls, rolling and turning wheel assemblies, plus authentic factory baked-enamel finishes (Green Hornet for Chicago and Cream and Crimson for Boston).',1645,N'37.49',N'58.58'),
(N'S50_4713',N'2002 Yamaha YZR M1',N'Motorcycles',N'1:50',N'Autoart Studio Design',N'Features rotating wheels , working kick stand. Comes with stand.',600,N'34.17',N'81.36'),
(N'S700_1138',N'The Schooner Bluenose',N'Ships',N'1:700',N'Autoart Studio Design',N'All wood with canvas sails. Measures 31 1/2 inches in Length, 22 inches High and 4 3/4 inches Wide. Many extras.
The schooner Bluenose was built in Nova Scotia in 1921 to fish the rough waters off the coast of Newfoundland. Because of the Bluenose racing prowess she became the pride of all Canadians. Still featured on stamps and the Canadian dime, the Bluenose was lost off Haiti in 1946.',1897,N'34.00',N'66.67'),
